/** 服务端单条接口 */
export interface ServerRoute {
  /** 请求路径，与 server.js 注册的路由一致 */
  path: string;
  /** 服务端 module 文件名 */
  module: string;
  /** 按路径首段划分的功能域 */
  domain: string;
  /** write 表示会提交数据，页面需二次确认 */
  kind: 'read' | 'write';
  /** 是否需要选择本地文件并以 FormData 提交 */
  file: boolean;
  /** 生成时前端源码里是否已引用（已有页面接入） */
  existing: boolean;
}

